/// Compute lateral load transfer for a 4-wheel vehicle during cornering.
///
/// Returns `(delta_front, delta_rear)` — the load transferred from
/// inner to outer wheels on each axle (N).
///
/// * `total_mass` — vehicle mass (kg).
/// * `lateral_accel` — lateral acceleration (m/s^2).
/// * `cg_height` — centre of gravity height (m).
/// * `track_width` — average track width (m).
/// * `front_weight_ratio` — fraction of weight on front axle (0–1).
pub fn lateral_load_transfer(
    total_mass: f64,
    lateral_accel: f64,
    cg_height: f64,
    track_width: f64,
    front_weight_ratio: f64,
) -> (f64, f64) {
    let total_transfer = total_mass * lateral_accel * cg_height / track_width.max(1e-6);
    let front = total_transfer * front_weight_ratio;
    let rear = total_transfer * (1.0 - front_weight_ratio);
    (front, rear)
}
/// Compute longitudinal load transfer during braking or acceleration.
///
/// Returns the load transferred from rear to front (positive = braking).
///
/// * `total_mass` — vehicle mass (kg).
/// * `longitudinal_accel` — deceleration (positive = braking, m/s^2).
/// * `cg_height` — CG height (m).
/// * `wheelbase` — axle-to-axle distance (m).
pub fn longitudinal_load_transfer(
    total_mass: f64,
    longitudinal_accel: f64,
    cg_height: f64,
    wheelbase: f64,
) -> f64 {
    total_mass * longitudinal_accel * cg_height / wheelbase.max(1e-6)
}
/// Compute the tire slip angle (radians) from wheel forward speed and lateral speed.
///
/// alpha = atan2(v_lateral, |v_forward|)
///
/// Positive slip angle means the wheel is sliding toward the right (yaw pushes car left).
pub fn slip_angle(v_forward: f64, v_lateral: f64) -> f64 {
    if v_forward.abs() < 1e-4 {
        return 0.0;
    }
    (v_lateral / v_forward.abs()).atan()
}
/// Compute the longitudinal slip ratio from wheel tangential speed and vehicle speed.
///
/// kappa = (omega * r - v) / max(|v|, |omega * r|)
///
/// Positive = acceleration (wheel spin > vehicle speed), negative = braking.
pub fn slip_ratio(omega: f64, radius: f64, vehicle_speed: f64) -> f64 {
    let wheel_speed = omega * radius;
    let denom = vehicle_speed.abs().max(wheel_speed.abs()).max(1e-4);
    (wheel_speed - vehicle_speed) / denom
}
/// Compute the combined slip magnitude used for Pacejka combined-slip scaling.
///
/// sigma = sqrt(kappa^2 + tan(alpha)^2)
pub fn combined_slip(kappa: f64, alpha: f64) -> f64 {
    (kappa * kappa + alpha.tan() * alpha.tan()).sqrt()
}
